-- Mark non-leaf nodes
UPDATE catalog.hsn_sac p SET is_leaf = false
WHERE EXISTS (
    SELECT 1 FROM catalog.hsn_sac c
    WHERE c.parent_code = p.code AND c.country_id = p.country_id AND c.code_type = p.code_type
);